css:
.m-3 {
  margin: 0.75rem
}

.block {
  display: block
}

.flex {
  display: flex
}

.h-14 {
  height: 3.5rem
}

.h-28 {
  height: 7rem
}

.w-14 {
  width: 3.5rem
}

.w-4 {
  width: 1rem
}

.w-7 {
  width: 1.75rem
}

.w-72 {
  width: 18rem
}

.items-center {
  align-items: center
}

.justify-center {
  justify-content: center
}

.gap-3 {
  gap: 0.75rem
}

.rounded-full {
  border-radius: 9999px
}

.rounded-md {
  border-radius: 0.375rem
}

.border-l {
  border-left-width: 1px
}

.border-gray-300 {
  --tw-border-opacity: 1;
  border-color: rgb(209 213 219 / var(--tw-border-opacity))
}

.bg-white {
  --tw-bg-opacity: 1;
  background-color: rgb(255 255 255 / var(--tw-bg-opacity))
}

.bg-gradient-to-l {
  background-image: linear-gradient(to left, var(--tw-gradient-stops))
}

.bg-gradient-to-r {
  background-image: linear-gradient(to right, var(--tw-gradient-stops))
}

.from-\[\#005BC4\] {
  --tw-gradient-from: #005BC4 var(--tw-gradient-from-position);
  --tw-gradient-to: rgb(0 91 196 / 0) var(--tw-gradient-to-position);
  --tw-gradient-stops: var(--tw-gradient-from), var(--tw-gradient-to)
}

.from-\[\#F9C97C\] {
  --tw-gradient-from: #F9C97C var(--tw-gradient-from-position);
  --tw-gradient-to: rgb(249 201 124 / 0) var(--tw-gradient-to-position);
  --tw-gradient-stops: var(--tw-gradient-from), var(--tw-gradient-to)
}

.to-\[\#27272A\] {
  --tw-gradient-to: #27272A var(--tw-gradient-to-position)
}

.to-\[\#A2E9C1\] {
  --tw-gradient-to: #A2E9C1 var(--tw-gradient-to-position)
}

.bg-clip-text {
  -webkit-background-clip: text;
  background-clip: text
}

.fill-gray-700 {
  fill: #374151
}

.fill-white {
  fill: #fff
}

.stroke-2 {
  stroke-width: 2
}

.p-3 {
  padding: 0.75rem
}

.pl-3 {
  padding-left: 0.75rem
}

.pt-2 {
  padding-top: 0.5rem
}

.text-lg {
  font-size: 1.125rem;
  line-height: 1.75rem
}

.text-sm {
  font-size: 0.875rem;
  line-height: 1.25rem
}

.font-bold {
  font-weight: 700
}

.font-semibold {
  font-weight: 600
}

.text-gray-600 {
  --tw-text-opacity: 1;
  color: rgb(75 85 99 / var(--tw-text-opacity))
}

.text-transparent {
  color: transparent
}

.shadow-lg {
  --tw-shadow: 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1);
  --tw-shadow-colored: 0 10px 15px -3px var(--tw-shadow-color), 0 4px 6px -4px var(--tw-shadow-color);
  box-shadow: var(--tw-ring-offset-shadow, 0 0 #0000), var(--tw-ring-shadow, 0 0 #0000), var(--tw-shadow)
}

.shadow-md {
  --tw-shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
  --tw-shadow-colored: 0 4px 6px -1px var(--tw-shadow-color), 0 2px 4px -2px var(--tw-shadow-color);
  box-shadow: var(--tw-ring-offset-shadow, 0 0 #0000), var(--tw-ring-shadow, 0 0 #0000), var(--tw-shadow)
}

.duration-200 {
  transition-duration: 200ms
}

.duration-300 {
  transition-duration: 300ms
}

.hover\:scale-110:hover {
  --tw-scale-x: 1.1;
  --tw-scale-y: 1.1;
  transform: translate(var(--tw-translate-x), var(--tw-translate-y)) rotate(var(--tw-rotate)) skewX(var(--tw-skew-x)) skewY(var(--tw-skew-y)) scaleX(var(--tw-scale-x)) scaleY(var(--tw-scale-y))
}

.hover\:scale-125:hover {
  --tw-scale-x: 1.25;
  --tw-scale-y: 1.25;
  transform: translate(var(--tw-translate-x), var(--tw-translate-y)) rotate(var(--tw-rotate)) skewX(var(--tw-skew-x)) skewY(var(--tw-skew-y)) scaleX(var(--tw-scale-x)) scaleY(var(--tw-scale-y))
}

.hover\:cursor-pointer:hover {
  cursor: pointer
}

.hover\:from-\[\#C9A9E9\]:hover {
  --tw-gradient-from: #C9A9E9 var(--tw-gradient-from-position);
  --tw-gradient-to: rgb(201 169 233 / 0) var(--tw-gradient-to-position);
  --tw-gradient-stops: var(--tw-gradient-from), var(--tw-gradient-to)
}

.hover\:to-\[\#7EE7FC\]:hover {
  --tw-gradient-to: #7EE7FC var(--tw-gradient-to-position)
}
